//! Official D&D lists (lineages, backgrounds, feats, gear, classes), built into the binary.
//! The JSON files in data/lists/ are generated by tools/fetch_lists.py.

use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};

use serde::Deserialize;

use crate::model::{ActionDef, Feature, ResourceDef, Toggle};

type Table = BTreeMap<u32, u32>;

// --- Lineages ----------------------------------------------------------------

#[derive(Deserialize, Clone)]
pub struct Choose { pub n: u32, pub amount: i32 }

#[derive(Deserialize, Clone, Default)]
pub struct Asi {
    #[serde(default)] pub fixed: BTreeMap<String, i32>,
    #[serde(default)] pub choose: Vec<Choose>,
}

#[derive(Deserialize, Clone, Default)]
#[serde(default)]
pub struct Section {
    pub asi: Option<Asi>,
    pub size: Option<String>,
    pub speed: Option<u32>,
    pub languages: Vec<String>,
    pub extra_languages: u32,
    pub skills: Vec<String>,
    pub extra_skills: u32,
    pub feats: u32,
    pub traits: Vec<Feature>,
}

#[derive(Deserialize)]
pub struct LineageSub {
    pub name: String,
    #[serde(default)] pub replaces: bool,
    #[serde(flatten)] pub sec: Section,
}

#[derive(Deserialize)]
pub struct Lineage {
    pub name: String,
    pub source: String,
    #[serde(flatten)] pub sec: Section,
    #[serde(default)] pub subs: Vec<LineageSub>,
}

/// What a lineage plus an optional subrace/variant actually gives.
#[derive(Default)]
pub struct Effective {
    pub fixed: BTreeMap<String, i32>,
    pub choose: Vec<Choose>,
    pub has_asi: bool,
    pub speed: Option<u32>,
    pub languages: Vec<String>,
    pub extra_languages: u32,
    pub skills: Vec<String>,
    pub extra_skills: u32,
    pub feats: u32,
    pub traits: Vec<Feature>,
}

impl Lineage {
    pub fn effective(&self, sub: Option<usize>) -> Effective {
        let base = &self.sec;
        let sub = sub.map(|i| &self.subs[i]);
        let mut e = Effective::default();
        let mut add = |asi: &Option<Asi>, e: &mut Effective| {
            if let Some(a) = asi {
                e.has_asi = true;
                for (k, v) in &a.fixed { *e.fixed.entry(k.clone()).or_insert(0) += v; }
                e.choose.extend(a.choose.iter().cloned());
            }
        };
        match sub {
            Some(s) if s.replaces && s.sec.asi.is_some() => add(&s.sec.asi, &mut e),
            Some(s) => { add(&base.asi, &mut e); add(&s.sec.asi, &mut e); }
            None => add(&base.asi, &mut e),
        }
        e.speed = sub.and_then(|s| s.sec.speed).or(base.speed);
        e.extra_languages = base.extra_languages + sub.map_or(0, |s| s.sec.extra_languages);
        e.extra_skills = base.extra_skills + sub.map_or(0, |s| s.sec.extra_skills);
        e.feats = base.feats + sub.map_or(0, |s| s.sec.feats);
        for sec in std::iter::once(base).chain(sub.map(|s| &s.sec)) {
            for l in &sec.languages { if !e.languages.contains(l) { e.languages.push(l.clone()); } }
            for sk in &sec.skills { if !e.skills.contains(sk) { e.skills.push(sk.clone()); } }
            for t in &sec.traits {
                match e.traits.iter_mut().find(|x| x.name == t.name) {
                    Some(x) => *x = t.clone(),
                    None => e.traits.push(t.clone()),
                }
            }
        }
        e
    }
}

// --- Backgrounds, feats, gear -----------------------------------------------------

#[derive(Deserialize)]
pub struct Background {
    pub name: String,
    pub source: String,
    #[serde(default)] pub skills: Vec<String>,
    #[serde(default)] pub extra_skills: u32,
    #[serde(default)] pub tools: String,
    #[serde(default)] pub languages: Vec<String>,
    #[serde(default)] pub extra_languages: u32,
    #[serde(default)] pub equipment: String,
    pub feature: Option<String>,
}

#[derive(Deserialize)]
pub struct FeatAsi { pub options: Vec<String>, pub amount: i32 }

#[derive(Deserialize)]
pub struct FeatDef {
    pub name: String,
    pub source: String,
    pub prereq: Option<String>,
    pub asi: Option<FeatAsi>,
    #[serde(default)] pub min_ability: BTreeMap<String, i32>,
    #[serde(default)] pub desc: String,
}

#[derive(Deserialize)]
pub struct Weapon {
    pub name: String,
    pub category: String, // "Simple Melee", "Martial Ranged", ...
    pub dice: (u32, u32),
    #[serde(rename = "type")] pub dmg_type: String,
    pub props: String,
    pub ranged: bool,
    pub finesse: bool,
    pub light: bool,
    pub two_handed: bool,
    pub thrown: Option<String>,
    pub ammunition: bool,
}

#[derive(Deserialize)]
pub struct Armor {
    pub name: String,
    pub category: String, // Light, Medium, Heavy, Shield
    pub ac: i32,
    pub dex: String,      // "full" | "max2" | "none"
}

// --- Classes -------------------------------------------------------------------------

#[derive(Deserialize)]
pub struct SkillChoice { pub choose: usize, pub from: Vec<String> }

#[derive(Deserialize)]
pub struct Style {
    pub name: String,
    pub source: String,
    pub desc: String,
    pub effect: Option<String>,
}

#[derive(Deserialize)]
pub struct Subclass {
    pub name: String,
    pub source: String,
    #[serde(default)] pub needs_spells: bool,
    #[serde(default)] pub resources: Vec<ResourceDef>,
    #[serde(default)] pub actions: Vec<ActionDef>,
    pub maneuver_pool: Option<String>,
    #[serde(default)] pub tables: BTreeMap<String, Table>,
    #[serde(default)] pub dice: BTreeMap<String, Table>,
    #[serde(default)] pub maneuvers_known: Table,
    #[serde(default)] pub features: BTreeMap<u32, Vec<Feature>>,
}

/// Unarmored Defense: AC is 10 + DEX + `ability` while no armor is worn.
#[derive(Deserialize)]
pub struct Unarmored { pub ability: String, pub shield: bool }

#[derive(Deserialize)]
pub struct ClassData {
    pub name: String,
    pub hit_die: u32,
    pub saves: Vec<String>,
    pub skills: SkillChoice,
    pub armor: Vec<String>,
    pub weapons: Vec<String>,
    #[serde(default)] pub tools: Vec<String>,
    #[serde(default)] pub equipment: Vec<String>,
    pub asi_levels: Vec<u32>,
    pub subclass_level: u32,
    pub subclass_title: String,
    pub attacks_per_action: Table,
    #[serde(default)] pub resources: Vec<ResourceDef>,
    #[serde(default)] pub tables: BTreeMap<String, Table>,
    #[serde(default)] pub actions: Vec<ActionDef>,
    #[serde(default)] pub toggles: Vec<Toggle>,
    pub unarmored: Option<Unarmored>,
    #[serde(default = "one")] pub style_level: u32, // level that grants a fighting style
    #[serde(default)] pub expertise: Vec<u32>, // levels that grant two skills with double proficiency
    pub features: BTreeMap<u32, Vec<Feature>>,
    #[serde(default)] pub styles: Vec<Style>,
    pub subclasses: Vec<Subclass>,
}

/// Level tables of a class merged with its subclass: what a level up looks at.
pub struct Progression {
    pub asi_levels: Vec<u32>,
    pub resources: BTreeMap<String, Table>,
    pub dice: BTreeMap<String, Table>,
    pub maneuvers_known: Table,
    pub attacks_per_action: Table,
    pub features: BTreeMap<u32, Vec<Feature>>,
}

fn one() -> u32 { 1 }

macro_rules! list {
    ($name:ident, $ty:ty, $file:literal) => {
        pub fn $name() -> &'static Vec<$ty> {
            static C: OnceLock<Vec<$ty>> = OnceLock::new();
            C.get_or_init(|| serde_json::from_str(include_str!(concat!("../data/lists/", $file))).expect($file))
        }
    };
}

list!(lineages, Lineage, "lineages.json");
list!(backgrounds, Background, "backgrounds.json");
list!(feats, FeatDef, "feats.json");
list!(weapons, Weapon, "weapons.json");
list!(armors, Armor, "armor.json");

pub fn classes() -> &'static Vec<ClassData> {
    static C: OnceLock<Vec<ClassData>> = OnceLock::new();
    C.get_or_init(|| {
        [include_str!("../data/lists/classes/fighter.json"), include_str!("../data/lists/classes/barbarian.json"),
         include_str!("../data/lists/classes/rogue.json"),
         include_str!("../data/lists/classes/monk.json"),
         include_str!("../data/lists/classes/paladin.json"), include_str!("../data/lists/classes/ranger.json")]
            .iter().map(|j| serde_json::from_str(j).expect("class json")).collect()
    })
}

pub fn class_data(name: &str) -> Option<&'static ClassData> { classes().iter().find(|c| c.name == name) }

pub fn progression(class: &str, sub: Option<&str>) -> Option<&'static Progression> {
    static CACHE: Mutex<BTreeMap<String, &'static Progression>> = Mutex::new(BTreeMap::new());
    let key = format!("{class}/{}", sub.unwrap_or(""));
    let mut cache = CACHE.lock().unwrap();
    if let Some(p) = cache.get(&key) { return Some(*p); }
    let cd = class_data(class)?;
    let sd = sub.and_then(|s| cd.subclasses.iter().find(|x| x.name == s));
    let mut p = Progression {
        asi_levels: cd.asi_levels.clone(),
        resources: cd.tables.clone(),
        dice: BTreeMap::new(),
        maneuvers_known: Table::new(),
        attacks_per_action: cd.attacks_per_action.clone(),
        features: cd.features.clone(),
    };
    if let Some(sd) = sd {
        p.resources.extend(sd.tables.clone());
        p.dice = sd.dice.clone();
        p.maneuvers_known = sd.maneuvers_known.clone();
        for (lvl, fs) in &sd.features { p.features.entry(*lvl).or_default().extend(fs.iter().cloned()); }
    }
    let leaked: &'static Progression = Box::leak(Box::new(p));
    cache.insert(key, leaked);
    Some(leaked)
}

/// Short book names for menus.
pub fn abbr(source: &str) -> String {
    const SHORT: [(&str, &str); 14] = [
        ("Player's Handbook", "PHB"), ("Xanathar's Guide to Everything", "XGtE"), ("Tasha's Cauldron of Everything", "TCoE"),
        ("Volo's Guide to Monsters", "VGtM"), ("Mordenkainen Presents: Monsters of the Multiverse", "MotM"),
        ("Mordenkainen's Tome of Foes", "MToF"), ("Sword Coast Adventurer's Guide", "SCAG"),
        ("Explorer's Guide to Wildemount", "EGtW"), ("Guildmaster's Guide to Ravnica", "GGtR"),
        ("Mythic Odysseys of Theros", "MOoT"), ("Fizban's Treasury of Dragons", "FToD"), ("Van Richten's Guide to Ravenloft", "VRGtR"),
        ("Elemental Evil Player's Companion", "EEPC"), ("Eberron - Rising from the Last War", "ERLW"),
    ];
    SHORT.iter().find(|(l, _)| *l == source).map_or_else(|| source.chars().take(28).collect::<String>().trim_end_matches(|c: char| c == '/' || c == ' ').to_string(), |(_, s)| s.to_string())
}
